// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes memory data, uint256 value) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(data.length <= 1000);
        value = bound(value, 0, 100 ether);

        address owner = c.Owner();
        bool reverted;

        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("Command(address,bytes)", address(0), data));
        reverted = !success;

        assertTrue(!success || caller == owner);
    }
}

